  "steps": [
    {
      "id": 1,
      "claim": "An item can be safely reused only if it can be fully decontaminated without loss of function and is not designated as a single‑use consumable by manufacturer or safety guidelines.",
      "evidence": "OSHA Laboratory Standard (29 CFR 1910.1450) and CDC/NIH laboratory safety guidelines distinguish reusable equipment (e.g., glassware) from disposable consumables (e.g., filter paper, paper towels).",
      "weight": 0.22,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Glassware used to heat liquids is non‑porous, chemically resistant, and can be washed, rinsed, and sterilized (autoclaved or oven‑dried) to remove all residues.",
      "evidence": "Standard laboratory SOPs and USP <797> require washing glassware with detergent, thorough rinsing, and sterilization before reuse.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Filter paper is a porous cellulose matrix that retains particulates and chemicals; cleaning cannot restore its original pore structure or guarantee removal of contaminants.",
      "evidence": "Manufacturer specifications label filter paper as disposable; laboratory protocols treat it as a single‑use consumable because it cannot be reliably decontaminated.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Paper towels are absorbent, single‑use disposables; their fibers trap liquids and any contaminants, making effective decontamination impossible.",
      "evidence": "Product labeling and waste‑management policies require disposal after one use; cleaning would leave residues and compromise hygiene.",
      "weight": 0.13,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Powdered chemicals recovered from a spill are considered contaminated waste because they may have mixed with unknown substances and their purity cannot be verified.",
      "evidence": "Chemical Hygiene Plans (CHP) and spill‑cleanup protocols mandate disposal of any reagent involved in a spill to prevent introduction of impurities or hazards.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "Applying the safe‑reuse criterion (step 1) to each option shows that only glassware satisfies the requirement; the other items fail because they are disposable or contaminated.",
      "evidence": "Steps 2‑5 evaluate each item against the criterion; only step 2 (glassware) meets it.",
      "weight": 0.15,
      "depends_on": [2, 3, 4, 5]
    }
  ],
  "answer": "A",
  "confidence": 0.97,
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "Filter paper is a disposable consumable; its porous structure retains contaminants and cannot be reliably cleaned for safe reuse."
    },
    {
      "answer": "C",
      "reason_rejected": "Paper towels are single‑use absorbents that become contaminated with the liquids they soak up; effective decontamination is not possible."
    },
    {
      "answer": "D",
      "reason_rejected": "Powdered chemicals recovered from a spill are potentially mixed with unknown substances, so their purity and safety cannot be assured; they must be treated as waste."
    }
